if((Get-FileHash -LiteralPath (Join-Path $Stage 'package\plan-prebuild-v4.json')).Hash.ToLowerInvariant() -cne '981ff4e72fb07e9e1ab0cde866d8a8cff12c6be23d1699f338509772043f6739'){throw 'corrected prebuild plan drift'}
